package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class KeyedObjects2D_removeObject_TriageGen1Test {

    private KeyedObjects2D dataset;

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test
    public void testRemoveObject_DoesNotRemoveRowOrColumnWhenOthersExist() {
        // Arrange
        Comparable row1 = "Row1";
        Comparable row2 = "Row2";
        Comparable col1 = "Col1";
        Comparable col2 = "Col2";

        dataset.addObject("Val1", row1, col1);
        dataset.addObject("Val2", row1, col2);
        dataset.addObject("Val3", row2, col1);

        // Act: Remove only one object
        dataset.removeObject(row1, col1);

        // Assert
        assertNull("Object at (row1, col1) should be null", dataset.getObject(row1, col1));
        assertEquals("Row1 should still exist because it has Col2", 2, dataset.getRowCount());
        assertEquals("Col1 should still exist because it has Row2", 2, dataset.getColumnCount());
        assertEquals("Val2 should still be present", "Val2", dataset.getObject(row1, col2));
        assertEquals("Val3 should still be present", "Val3", dataset.getObject(row2, col1));
    }

    @Test
    public void testRemoveObject_RemovesRowWhenEmpty() {
        // Arrange
        Comparable row1 = "Row1";
        Comparable col1 = "Col1";
        dataset.addObject("Val1", row1, col1);

        // Act
        dataset.removeObject(row1, col1);

        // Assert
        assertEquals("Row should be removed from dataset", 0, dataset.getRowCount());
    }

    @Test
    public void testRemoveObject_RemovesColumnWhenEmpty() {
        // Arrange
        Comparable row1 = "Row1";
        Comparable row2 = "Row2";
        Comparable col1 = "Col1";

        dataset.addObject("Val1", row1, col1);
        dataset.addObject("Val2", row2, col1);

        // Act: Remove all objects in Col1
        dataset.removeObject(row1, col1);
        dataset.removeObject(row2, col1);

        // Assert
        assertEquals("Column should be removed from dataset", 0, dataset.getColumnCount());
        assertEquals("Rows should still exist (but empty)", 2, dataset.getRowCount());
    }

    @Test
    public void testRemoveObject_RemovesBothWhenLastObject() {
        // Arrange
        Comparable row1 = "Row1";
        Comparable col1 = "Col1";
        dataset.addObject("Val1", row1, col1);

        // Act
        dataset.removeObject(row1, col1);

        // Assert
        assertEquals(0, dataset.getRowCount());
        assertEquals(0, dataset.getColumnCount());
    }

    @Test
    public void testRemoveObject_NonExistentKeys() {
        // Arrange
        dataset.addObject("Val1", "R1", "C1");

        // Act: Remove non-existent key
        dataset.removeObject("NonExistentRow", "C1");

        // Assert: Dataset should remain unchanged
        assertEquals(1, dataset.getRowCount());
        assertEquals("Val1", dataset.getObject("R1", "C1"));
    }

    @Test
    public void testRemoveObject_PartialColumnCleanup() {
        // Arrange
        // Setup a scenario where a column is "empty" of non-null objects, 
        // but the row-level removal logic and column-level removal logic are both triggered.
        Comparable r1 = "R1";
        Comparable r2 = "R2";
        Comparable c1 = "C1";
        Comparable c2 = "C2";

        dataset.addObject("V1", r1, c1);
        dataset.addObject("V2", r1, c2);
        dataset.addObject("V3", r2, c2);

        // Act: Remove V1. 
        // Row R1 is NOT empty (has V2). 
        // Column C1 IS empty (only had V1).
        dataset.removeObject(r1, c1);

        // Assert
        assertNull(dataset.getObject(r1, c1));
        assertEquals(2, dataset.getRowCount()); // R1, R2 still exist
        assertEquals(1, dataset.getColumnCount()); // Only C2 remains
        assertEquals("V2", dataset.getObject(r1, c2));
    }
}
